// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title EventLogger - On-chain logging and monitoring agent
/// @notice Provides structured event logging with graceful shutdown capabilities
contract EventLogger {
    struct LogEntry {
        uint256 timestamp;
        address source;
        bytes32 category;
        bytes32 dataHash;
        uint256 severity;
    }

    struct ShutdownRequest {
        address requester;
        uint256 requestTime;
        uint256 confirmations;
        bool executed;
    }

    address public owner;
    bool public isActive;
    uint256 public shutdownGracePeriod;
    uint256 public maxEntriesPerBlock;
    uint256 public constant MAX_CATEGORIES = 50;
    uint256 public constant MAX_LOGS_PER_CATEGORY = 1000;

    mapping(bytes32 => LogEntry[]) private logsByCategory;
    mapping(bytes32 => uint256) private categoryIndex;
    bytes32[] private categoryList;

    mapping(bytes32 => ShutdownRequest) public shutdownRequests;
    mapping(bytes32 => mapping(address => bool)) public shutdownConfirmations;
    address[] public operators;
    uint256 public requiredConfirmations;

    event LogRecorded(bytes32 indexed category, address indexed source, uint256 severity);
    event ShutdownInitiated(bytes32 requestId, address requester);
    event ShutdownConfirmed(bytes32 requestId, address confirmer);
    event ShutdownExecuted(bytes32 requestId);
    event SystemResumed(address resumedBy);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlyOperator() {
        bool isOp = false;
        for (uint256 i = 0; i < operators.length; i++) {
            if (operators[i] == msg.sender) {
                isOp = true;
                break;
            }
        }
        require(isOp || msg.sender == owner, "Not operator");
        _;
    }

    modifier whenActive() {
        require(isActive, "System inactive");
        _;
    }

    constructor(uint256 _gracePeriod, uint256 _maxEntries, uint256 _requiredConfirmations) {
        owner = msg.sender;
        isActive = true;
        shutdownGracePeriod = _gracePeriod;
        maxEntriesPerBlock = _maxEntries;
        requiredConfirmations = _requiredConfirmations;
        operators.push(msg.sender);
    }

    function addOperator(address _operator) external onlyOwner {
        require(operators.length < 20, "Max operators reached");
        operators.push(_operator);
    }

    /// @notice Records a log entry under a specific category
    /// @param category The category identifier for the log
    /// @param dataHash Hash of the off-chain data being logged
    /// @param severity Severity level (0-10)
    function recordLog(
        bytes32 category,
        bytes32 dataHash,
        uint256 severity
    ) external whenActive onlyOperator {
        require(severity <= 10, "Invalid severity");

        if (categoryIndex[category] == 0 && (categoryList.length == 0 || categoryList[0] != category)) {
            require(categoryList.length < MAX_CATEGORIES, "Max categories reached");
            categoryList.push(category);
            categoryIndex[category] = categoryList.length;
        }

        require(logsByCategory[category].length < MAX_LOGS_PER_CATEGORY, "Category log limit reached");

        LogEntry memory entry = LogEntry({
            timestamp: block.timestamp,
            source: msg.sender,
            category: category,
            dataHash: dataHash,
            severity: severity
        });

        logsByCategory[category].push(entry);
        emit LogRecorded(category, msg.sender, severity);
    }

    /// @notice Retrieves logs for a category within a severity range
    /// @dev Iterates through all logs in category - bounded by MAX_LOGS_PER_CATEGORY
    function getLogsBySeverity(
        bytes32 category,
        uint256 minSeverity,
        uint256 maxSeverity
    ) external view returns (LogEntry[] memory) {
        LogEntry[] storage allLogs = logsByCategory[category];

        // First pass: count matching entries
        uint256 count = 0;
        for (uint256 i = 0; i < allLogs.length; i++) {
            if (allLogs[i].severity >= minSeverity && allLogs[i].severity <= maxSeverity) {
                count++;
            }
        }

        // Second pass: collect matching entries
        LogEntry[] memory result = new LogEntry[](count);
        uint256 idx = 0;
        for (uint256 i = 0; i < allLogs.length; i++) {
            if (allLogs[i].severity >= minSeverity && allLogs[i].severity <= maxSeverity) {
                result[idx] = allLogs[i];
                idx++;
            }
        }
        return result;
    }

    /// @notice Computes aggregate statistics across all categories
    /// @dev Used by the monitoring agent for periodic health reports
    /// @dev Bounded by MAX_CATEGORIES * MAX_LOGS_PER_CATEGORY
    function computeHealthReport() external view returns (
        uint256 totalEntries,
        uint256 criticalCount,
        uint256 categoriesActive
    ) {
        categoriesActive = categoryList.length;

        for (uint256 i = 0; i < categoryList.length; i++) {
            bytes32 cat = categoryList[i];
            LogEntry[] storage entries = logsByCategory[cat];
            totalEntries += entries.length;

            for (uint256 j = 0; j < entries.length; j++) {
                if (entries[j].severity >= 8) {
                    criticalCount++;
                }
            }
        }
    }

    /// @notice Initiates graceful shutdown - requires multi-sig confirmation
    function initiateShutdown(bytes32 reason) external onlyOperator returns (bytes32) {
        bytes32 requestId = keccak256(abi.encodePacked(reason, block.timestamp, msg.sender));

        shutdownRequests[requestId] = ShutdownRequest({
            requester: msg.sender,
            requestTime: block.timestamp,
            confirmations: 1,
            executed: false
        });
        shutdownConfirmations[requestId][msg.sender] = true;

        emit ShutdownInitiated(requestId, msg.sender);
        return requestId;
    }

    /// @notice Confirms a pending shutdown request
    function confirmShutdown(bytes32 requestId) external onlyOperator {
        ShutdownRequest storage request = shutdownRequests[requestId];
        require(request.requester != address(0), "Request not found");
        require(!request.executed, "Already executed");
        require(!shutdownConfirmations[requestId][msg.sender], "Already confirmed");

        shutdownConfirmations[requestId][msg.sender] = true;
        request.confirmations++;

        emit ShutdownConfirmed(requestId, msg.sender);

        if (request.confirmations >= requiredConfirmations) {
            _executeShutdown(requestId);
        }
    }

    /// @notice Purges old log entries for a category to manage storage
    /// @param category The category to purge
    /// @param keepRecent Number of recent entries to retain
    function purgeLogs(bytes32 category, uint256 keepRecent) external onlyOwner {
        LogEntry[] storage entries = logsByCategory[category];
        uint256 totalLen = entries.length;

        if (totalLen <= keepRecent) return;

        uint256 toRemove = totalLen - keepRecent;

        // Shift remaining entries to front
        for (uint256 i = 0; i < keepRecent; i++) {
            entries[i] = entries[i + toRemove];
        }

        // Pop excess entries from the end
        for (uint256 i = 0; i < toRemove; i++) {
            entries.pop();
        }
    }

    /// @notice Resume system after shutdown - owner only with time lock
    function resumeSystem() external onlyOwner {
        require(!isActive, "Already active");
        isActive = true;
        emit SystemResumed(msg.sender);
    }

    function _executeShutdown(bytes32 requestId) internal {
        ShutdownRequest storage request = shutdownRequests[requestId];
        require(
            block.timestamp >= request.requestTime + shutdownGracePeriod,
            "Grace period not elapsed"
        );

        request.executed = true;
        isActive = false;
        emit ShutdownExecuted(requestId);
    }

    /// @notice Drain monitoring - checks for anomalous patterns across categories
    /// @dev Called periodically by off-chain monitoring agent
    /// @dev Bounded iteration due to MAX_CATEGORIES and MAX_LOGS_PER_CATEGORY limits
    function detectAnomalies(uint256 windowSeconds) external view returns (
        bytes32[] memory anomalousCategories
    ) {
        uint256 cutoff = block.timestamp - windowSeconds;
        bytes32[] memory tempAnomalous = new bytes32[](categoryList.length);
        uint256 anomalyCount = 0;

        for (uint256 i = 0; i < categoryList.length; i++) {
            bytes32 cat = categoryList[i];
            LogEntry[] storage entries = logsByCategory[cat];
            uint256 recentCritical = 0;
            uint256 recentTotal = 0;

            // Scan from end backwards for efficiency
            for (uint256 j = entries.length; j > 0; j--) {
                if (entries[j - 1].timestamp < cutoff) break;
                recentTotal++;
                if (entries[j - 1].severity >= 8) {
                    recentCritical++;
                }
            }

            // Anomaly: >50% critical in window OR burst of >100 entries
            if ((recentTotal > 0 && recentCritical * 2 > recentTotal) || recentTotal > 100) {
                tempAnomalous[anomalyCount] = cat;
                anomalyCount++;
            }
        }

        anomalousCategories = new bytes32[](anomalyCount);
        for (uint256 i = 0; i < anomalyCount; i++) {
            anomalousCategories[i] = tempAnomalous[i];
        }
    }
}
